    EZTR_Basic_ReplaceText(0x125F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Eh, " "\xAE" "no eres Mikau?" "\x11" "\xAE" "Has conseguido que los castores" "\x11" "de la " "\x01" "cascada" "\x00" " te den una botella?" "\x19" "\xBF" "", NULL);
