    EZTR_Basic_ReplaceText(0x1269, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Tengo una tienda en el Sal" "\xA6" "n" "\x11" "Zora, as" "\xA1" " que si quieres ir all" "\xA1" " y" "\x11" "comprar algo..." "\xE0" "\xBF" "", NULL);
